import { readFileSync, writeFileSync, readdirSync } from "node:fs";

const step6 =
  "6. When a `principles/` folder exists, read its `README.md` and the principles relevant to the task — they are the long-lived values that standards and reviews appeal to; follow `rfc/` and `docs/` over them for concrete rules\n";

const steps78 = `7. When \`graphify-out/graph.json\` exists, use the committed knowledge graph before broad source browsing:
   - For codebase questions, run \`graphify query "<question>"\` first. Use \`graphify path "<A>" "<B>"\` for relationships and \`graphify explain "<concept>"\` for focused concepts.
   - Use \`graphify-out/wiki/index.md\` for broad navigation when it exists.
   - Read \`graphify-out/GRAPH_REPORT.md\` only for broad architecture review or when targeted queries do not surface enough context.
   - After modifying code, run \`graphify update .\` to keep the graph current (AST-only, no API cost).
8. Use the Repomix MCP server to pack the codebase into one digest and grep/read it for codebase-wide analysis instead of loading every file
`;

const graphifySection = /\n## 18\. Graphify\n\nWhen `graphify-out\/graph\.json` exists[\s\S]*$/;
const repomixBullet =
  "- **Repomix MCP server** — pack the codebase into one digest and grep/read it for codebase-wide analysis instead of loading every file\n";

for (const f of readdirSync("rules").filter((n) => n.endsWith(".md"))) {
  const path = `rules/${f}`;
  let raw = readFileSync(path, "utf8");
  if (!raw.includes(step6)) throw new Error(`${path}: step 6 anchor not found`);
  if (!graphifySection.test(raw)) throw new Error(`${path}: graphify section not found`);
  if (!raw.includes(repomixBullet)) throw new Error(`${path}: repomix bullet not found`);
  raw = raw.replace(step6, step6 + steps78);
  raw = raw.replace(graphifySection, "\n");
  raw = raw.replace(repomixBullet, "");
  writeFileSync(path, raw);
  console.log(`✓ ${path}`);
}
EOF
